rce_sku_id as product_id, cast(total_quantity as double precision) as quantity, upper(coalesce(lm.city,source_city_name::varchar)) AS city, upper(lm.state) AS state, sku_description::varchar as product_name, row_number() over (partition by cast(date_range_end as date),source_sku_id::varchar,source_city_name::varchar order by _airbyte_emitted_at desc) as rw from public.bigbasket_anveshan_analytics_manufacturer_sales bb LEFT JOIN (select * FROM ( select upper(city::varchar) as City, upper(trim(state::varchar)) as State, upper(trim(\"quick commerce city\"::varchar)) as qc_city_name, row_number() over (partition by upper(trim(\"quick commerce city\"::varchar)) order by 1) as rw FROM public.anveshan_qc_location_mapping ) where rw = 1 ) lm ON lower(lm.qc_city_name) = lower(cast(bb.source_city_name as varchar)) union ALL select * from public.bigbasket_sept_data union ALL ( SELECT cast(date_range_end as date) as order_date, cast(total_mrp as double precision) as total_mrp, brand_slug::varchar as brand, sku_weight as size, cast(total_sales as double precision) as total_sales, source_sku_id as product_id, cast(total_quantity as double precision) as quantity, upper(coalesce(lm.city,source_city_name::varchar)) AS city, upper(lm.state) AS state, sku_description::varchar as product_name, row_number() over (partition by cast(date_range_end as date),business_type::varchar,source_sku_id::varchar,source_city_name::varchar order by cast(date_range_end as date) desc) as rw from public.bigbasket_new_sale_orders_report bb LEFT JOIN (select * FROM ( select upper(city::varchar) as City, upper(trim(state::varchar)) as State, upper(trim(\"quick commerce city\"::varchar)) as qc_city_name, row_number() over (partition by upper(trim(\"quick commerce city\"::varchar)) order by 1) as rw FROM public.anveshan_qc_location_mapping ) where rw = 1 ) lm ON lower(lm.qc_city_name) = lower(cast(bb.source_city_name as varchar)) WHERE cast(date_range_end as date) > \'2026-10-06\' or cast(date_range_end as date) < \'2026-08-25\' ) ) b LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, bigbasket_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY bigbasket_sku ORDER BY LENGTH(COALESCE(bigbasket_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON LOWER(REPLACE(REPLACE(b.product_id::varchar, \' \', \'\'),\'\"\',\'\')) = LOWER(p.marketplace_sku) where b.rw = 1 ) ;",
